  const thumbs = [...document.querySelectorAll('#hGal .pkC img.pkT')].filter(i => i.complete && i.naturalWidth > 0 && vis(i)).length, arrows = ['hPrev', 'hNext', 'hPick'].some(id => vis(document.getElementById(id)));
